35 {"id": "GR7-J16-002", "canonical_id": "GR7-J16-002", "aliases": [], "classification": "required", "severity_proposed": "P3", "status": "REQUIRED_OPEN_FOR_MANUAL_UPDATE", "proposer": "R7-J16", "source_proposal_path": "tasks/R7-J16/findings.json", "original_proposal": {"id": "GR7-J16-002", "status": "PROPOSED", "title": "满经验槽闪光的逻辑色请求被写为“闪白”", "severity": "P3", "recommendation": "optional/request-level precision; ROOT_NONAUTHOR_REVIEW_REQUIRED", "kind": "MAIN_CONTRACT_PRESENTATION_WORDING", "location": {"file": "F7", "lines": [196, 248], "target": "仅两处0.2秒“闪白”；K22/K35没有该颜色断言，不判这些测试错误。"}, "seven_groups": {"1_identity_and_scope": "固定R数据框/场景定义及当前B正文；仅比较静态RGBA色请求，不声称最终像素或真实听感。", "2_precise_claim_and_fact": "数据框满经验分支以同一颜色请求作用于框及其子精灵，RGBA=(64,200,248,192)，并非白色RGB。0.2秒目标和满槽音效正确，不提出修改时长/声音/经验。", "3_complete_minimal_premises": {"state": "已正常建立的玩家单席数据框、合法非蛋成员、可见经验条；本级正区间，旧显示经验低于新值，新值等于级间满槽", "entry": "正常经验条动画更新，首次到达满槽且未已有闪光起点", "dependencies": "资源/时钟/图形接口正常，无并发外部闪光/插件覆写；只观察交付的颜色参数", "observer": "数据框及各已建立子精灵收到的flash颜色与时长请求。"}, "4_producer_consumer_and_phases": {"normal": "经验已提交→比例补间到端→设满槽闪光起点→停旧SE/请求满槽SE→请求蓝青色/名义0.2秒闪光→后继更新到期才清动画字段。", "cancel": "本组件无玩家取消分支；外层中止为独立合同。", "reject": "无条、无变化或零范围时不启动该经验动画；不套满槽闪光。", "failure": "前序更新/SE/图形请求失败可阻断后序，某个精灵已收请求不保证其他精灵全部收到。", "partial_commit": "持久经验及先行显示值不回滚；闪光是呈现请求，不能推出像素。"}, "5_counterexample_controls_and_negative": {"counterexample": "满足上述夹具时首个满槽flash请求的RGB为64/200/248；将“闪白”解释为白色请求会得到255/255/255。", "near_control": "非满经验段无满槽闪光；多席框不启动经验动画；正常满槽仍保持0.2秒、既有等待/音效。", "negative_evidence": "新读S6完整数据框L1–413、满槽分支及对应驱动；没有把数字显示取整、宿主混色或素材遮挡当色请求替代。全历史同根去重未穷尽，交根处理。", "strongest_counterargument": "“闪白”可能只是中文对亮闪的近似描述；宿主混色的最终像素也不由原始色参数唯一决定。若根接受近似表述，则仅可选精度同步。"}, "6_narrow_revision_and_preservation": {"minimal_revision": "可选将两处改为“0.2秒闪光”，或明确逻辑蓝青色RGBA请求及像素保留。", "read_set": ["S6:L163–203", "S6:L350–386", "S4:L234–254", "F7:L195–198", "F7:L244–249"], "write_set_if_approved": ["WP67-A L196/L248两处颜色措辞；可选新增仅请求层静态向量"], "preserve": ["满条比例1.75秒/满0.2秒与音效", "实际经验先写、逐级成长